const campaignStatusLabels = {
  PLANEJADA: 'Planejada',
  ATIVA: 'Ativa',
  PAUSADA: 'Pausada',
  FINALIZADA: 'Finalizada'
};

function normalizeCampaigns(campaigns = []) {
  return campaigns.map((campaign) => ({
    ...campaign,
    status: campaignStatusLabels[campaign.status] || campaign.status
  }));
}

function campaignBelongsToAssociation(campaign, association) {
  if (!campaign || !association) return false;
  const references = [campaign.associationId, campaign.associationSlug, campaign.association]
    .filter(Boolean)
    .map((value) => String(value).trim().toLowerCase());
  return [association.id, association.slug, association.name]
    .filter(Boolean)
    .map((value) => String(value).trim().toLowerCase())
    .some((value) => references.includes(value));
}

function scopedAssociationsForUser(associations, user) {
  if (isAdminUser(user)) return associations;
  const slug = associationSlugForUser(user);
  const association = associations.find((item) => item.id === slug)
    || associations.find((item) => item.name === user?.associationName)
    || {
      id: slug,
      name: user?.associationName || user?.name || 'Associação',
      region: 'Território da associação',
      status: 'Ativa',
      campaigns: 0,
      leads: 0,
      hot: 0,
      studies: 0,
      districts: 0,
      conversion: 0,
      featured: true
    };
  return [association];
}

function scopedRecordsForUser(records, user) {
  if (isAdminUser(user)) return records;
  return associationSlugForUser(user) === 'paulistana' ? records : [];
}

