function whatsappHistoryForLead(lead) {
  const history = [];
  const savedMessages = Array.isArray(lead.whatsappMessages) ? lead.whatsappMessages : [];
  if (savedMessages.length) {
    const outboundCount = savedMessages.filter((message) => (
      message.direction === 'OUTBOUND'
      && !message.metadata?.failure
      && !String(message.providerStatus || '').toUpperCase().startsWith('FAILED')
    )).length;
    const lastMessage = savedMessages[savedMessages.length - 1];
    const lastMessageAt = lastMessage?.sentAt || lastMessage?.receivedAt || lastMessage?.createdAt;
    history.push({
      title: 'Histórico registrado no WhatsApp',
      detail: `${formatNumber(savedMessages.length)} mensagem(ns) na conversa, com ${formatNumber(outboundCount)} envio(s) realizado(s)${lastMessageAt ? `. Última atividade em ${new Date(lastMessageAt).toLocaleString('pt-BR')}` : ''}.`,
      tone: 'bg-emerald-500/10 border-emerald-400/20 text-emerald-100'
    });
  }
  if (lead.desc && lead.desc !== 'N/I') {
    history.push({
      title: 'Conversa registrada',
      detail: lead.desc,
      tone: 'bg-emerald-500/10 border-emerald-400/20 text-emerald-100'
    });
  }
  if (lead.c !== null && lead.c !== undefined) {
    history.push({
      title: 'Último contato',
      detail: `Contato em ${formatBrDateOnly(lead.lastContactDate)}. Decorrido até hoje: ${formatElapsedContactTime(lead.c)} (${formatNumber(lead.c)} dias).`,
      tone: 'bg-blue-500/10 border-blue-400/20 text-blue-100'
    });
  }
  if (lead.e) {
    history.push({
      title: 'Estudo em andamento',
      detail: 'O material aparece como em andamento e deve continuar no acompanhamento.',
      tone: 'bg-violet-500/10 border-violet-400/20 text-violet-100'
    });
  }
  if (!history.length) {
    history.push({
      title: 'Sem conversa importada',
      detail: 'Este lead ainda não possui texto de conversa do WhatsApp nos dados carregados.',
      tone: 'bg-slate-500/10 border-slate-400/20 text-slate-200'
    });
  }
  return history;
}

