  async function loadLeadDirectory(seedLeads = []) {
    const fallbackDistricts = Array.from(new Set(records.map((lead) => lead.d).filter(Boolean))).sort((a, b) => a.localeCompare(b));
    const recordFallbackLeads = records
      .filter((lead) => lead.t && phoneDigits(lead.tel))
      .map(dashboardLeadToWhatsAppLead)
      .slice(0, 250);
    const fallbackLeadsByPhone = new Map();
    [...recordFallbackLeads, ...seedLeads].forEach((lead) => {
      const phone = phoneDigits(lead.phone || lead.tel);
      if (!phone) return;
      fallbackLeadsByPhone.set(phone.slice(-10), {
        ...lead,
        phone,
        name: lead.name || lead.n || `Contato ${phone.slice(-4)}`,
        district: lead.district || lead.d || null
      });
    });
    const fallbackLeads = Array.from(fallbackLeadsByPhone.values());
    setLeadDirectory(fallbackLeads);
    setLeadDistricts(fallbackDistricts);
    setLeadDirectoryLoading(true);
    try {
      const params = new URLSearchParams({ limit: '250' });
      const [response, countsResponse, campaignCountsResponse] = await Promise.all([
        apiFetch(`/api/whatsapp/leads?${params.toString()}`, { cache: 'no-store' }),
        apiFetch('/api/whatsapp/contact-counts', { cache: 'no-store' }).catch(() => null),
        apiFetch('/api/whatsapp/campaign-contact-counts', { cache: 'no-store' }).catch(() => null)
      ]);
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.message || 'Não foi possível buscar os leads.');
      if (countsResponse?.ok) {
        const countsPayload = await countsResponse.json();
        const nextCounts = {};
        for (const item of countsPayload.counts || []) {
          const countPhone = phoneDigits(item.phone);
          const count = Number(item.count || 0);
          const exactKey = `phone:${countPhone.slice(-10)}`;
          const suffixKey = `suffix:${countPhone.slice(-8)}`;
          nextCounts[exactKey] = (nextCounts[exactKey] || 0) + count;
          nextCounts[suffixKey] = (nextCounts[suffixKey] || 0) + count;
        }
        setWhatsappContactCounts(nextCounts);
      }
      if (campaignCountsResponse?.ok) {
        const campaignCountsPayload = await campaignCountsResponse.json();
        const nextCampaignCounts = {};
        for (const item of campaignCountsPayload.counts || []) {
          const countPhone = phoneDigits(item.phone);
          const campaignContacts = Array.isArray(item.campaigns) ? item.campaigns : [];
          nextCampaignCounts[`phone:${countPhone.slice(-10)}`] = campaignContacts;
          nextCampaignCounts[`suffix:${countPhone.slice(-8)}`] = campaignContacts;
        }
        setCampaignContactCounts(nextCampaignCounts);
      }
      const mergedLeads = new Map();
      [...fallbackLeads, ...(payload.leads || [])].forEach((lead) => {
        const key = phoneDigits(lead.phone).slice(-10) || lead.id;
        const existing = mergedLeads.get(key) || {};
        mergedLeads.set(key, { ...existing, ...lead });
      });
      setLeadDirectory(Array.from(mergedLeads.values()).slice(0, 250));
      setLeadDistricts(Array.from(new Set([...fallbackDistricts, ...(payload.districts || [])])).sort((a, b) => a.localeCompare(b)));
    } catch (error) {
      setLeadDirectory(fallbackLeads);
      setLeadDistricts(fallbackDistricts);
      if (!fallbackLeads.length) toast.error('Falha ao buscar leads', { description: error.message });
    } finally {
      setLeadDirectoryLoading(false);
    }
  }

